void generate_torus_mesh(float major_radius, float minor_radius, int num_theta, int num_phi,
                        float **vertices, int *num_vertices, float **indices, int *num_indices) {
    // Initialize vertices array
    *vertices = (float*)malloc(sizeof(float) * 3 * (num_theta * num_phi));
    *num_vertices = num_theta * num_phi;

    // Initialize indices array
    *indices = (float*)malloc(sizeof(float) * 3 * (num_theta * num_phi - 2));
    *num_indices = 3 * (num_theta * num_phi - 2);

    // Generate vertex data
    for (int theta = 0; theta < num_theta; theta++) {
        for (int phi = 0; phi < num_phi; phi++) {
            float angle_theta = theta * 2 * PI / num_theta;
            float angle_phi = phi * 2 * PI / num_phi;
            float x = (major_radius + minor_radius * cos(angle_phi)) * cos(angle_theta);
            float y = (major_radius + minor_radius * cos(angle_phi)) * sin(angle_theta);
            float z = minor_radius * sin(angle_phi);

            // Store vertex data
            int index = theta * num_phi + phi;
            vertices[index * 3] = x;
            vertices[index * 3 + 1] = y;
            vertices[index * 3 + 2] = z;
        }
    }

    // Generate index data (triangle mesh)
    int index = 0;
    for (int theta = 0; theta < num_theta - 1; theta++) {
        for (int phi = 0; phi < num_phi - 1; phi++) {
            indices[index++] = theta * num_phi + phi;
            indices[index++] = theta * num_phi + phi + 1;
            indices[index++] = (theta + 1) * num_phi + phi;

            indices[index++] = (theta + 1) * num_phi + phi;
            indices[index++] = theta * num_phi + phi + 1;
            indices[index++] = (theta + 1) * num_phi + phi + 1;
        }
    }
}
